using System.IO;
using Dream.Assets;

namespace Dream.Rendering.Props;

// The world props: rigid, unskinned glTF models with a baked albedo atlas, generated by
// tools/ui-assets/gen_props.py into animations/props/. Seven of them are the meshes of the sprite objects
// gen_iso_*.py drew and nothing consumed (barrel, oak, bramble, slate, tombstone, bones, the rune flask);
// the rest are what a hamlet needs. They are client-visual scenery: nothing here collides.
public enum PropKind
{
    RustBarrel,
    DeadOak,
    Bramble,
    SlateRocks,
    Tombstone,
    BonePile,
    RuneFlask,
    Brazier,
    Well,
    Cart,
    Fence,
    FenceBroken,
    Crates,
    Sacks,
    Woodpile,
    Signpost,
    Scarecrow,
    Cottage,
    Inn,
    Hovel,
    RuinedWall,
    StandingStones,
}

// What a placement needs to know about a kind: where its model is, how much ground it covers (half extents in
// world units on the prop's own x / z axes, front = +z) and how uneven that ground may be. Footprints come from
// the generator's authored sizes (gen_props.WORLD_UNITS_PER_U = 0.039 world units per u: the player is 1.2).
public readonly record struct PropFootprint(float HalfWidth, float HalfDepth, int MaxSpread)
{
    // The largest half extent: the radius the renderer culls with.
    public float Radius => MathF.Sqrt((HalfWidth * HalfWidth) + (HalfDepth * HalfDepth));
}

// The coarse box a model fits in, for the frustum test: a horizontal half extent from its origin (the sphere that
// holds the model, so any heading fits) and its height. Measured from the shipped GLBs; generous on purpose.
public readonly record struct PropBounds(float HorizontalRadius, float Height);

public static class PropCatalog
{
    public const int KindCount = 22;

    private static readonly PropBounds[] BoundsByKind =
    [
        new(0.75f, 0.9f),    // RustBarrel
        new(2.9f, 4.1f),     // DeadOak
        new(1.8f, 1.2f),     // Bramble
        new(1.4f, 1.1f),     // SlateRocks
        new(0.9f, 1.5f),     // Tombstone
        new(1.2f, 0.6f),     // BonePile
        new(0.35f, 0.6f),    // RuneFlask
        new(0.5f, 0.6f),     // Brazier
        new(1.55f, 2.3f),    // Well
        new(1.8f, 1.0f),     // Cart
        new(0.95f, 1.0f),    // Fence
        new(0.95f, 1.0f),    // FenceBroken
        new(1.05f, 1.0f),    // Crates
        new(0.85f, 0.9f),    // Sacks
        new(1.3f, 0.8f),     // Woodpile
        new(1.4f, 2.3f),     // Signpost
        new(1.2f, 2.0f),     // Scarecrow
        new(3.1f, 3.5f),     // Cottage
        new(4.3f, 3.9f),     // Inn
        new(2.7f, 3.3f),     // Hovel
        new(2.0f, 1.2f),     // RuinedWall
        new(1.6f, 1.4f),     // StandingStones
    ];

    public static PropBounds Bounds(PropKind kind) => BoundsByKind[(int)kind];

    private static readonly string[] FileStems =
    [
        "rust_barrel", "dead_oak", "bramble", "slate_rocks", "tombstone", "bone_pile", "rune_flask", "brazier", "well",
        "cart", "fence", "fence_broken", "crates", "sacks", "woodpile", "signpost", "scarecrow", "cottage", "inn", "hovel",
        "ruined_wall", "standing_stones",
    ];

    // A building may stand on ground that differs by one cell across its footprint (its stone footing reaches a cell
    // below the ground, so the low side shows a plinth); everything else needs level ground.
    private static readonly PropFootprint[] Footprints =
    [
        new(0.4f, 0.4f, 0),    // RustBarrel
        new(1.4f, 1.2f, 0),    // DeadOak (its low limbs droop, so the ground it needs is wider than the trunk)
        new(1.0f, 1.0f, 0),    // Bramble
        new(0.75f, 0.7f, 0),   // SlateRocks
        new(0.4f, 0.4f, 0),    // Tombstone
        new(0.8f, 0.5f, 0),    // BonePile
        new(0.2f, 0.2f, 0),    // RuneFlask
        new(0.3f, 0.3f, 0),    // Brazier
        new(0.85f, 0.85f, 0),  // Well
        new(0.7f, 1.5f, 0),    // Cart
        new(0.8f, 0.2f, 0),    // Fence
        new(0.8f, 0.25f, 0),   // FenceBroken
        new(0.55f, 0.55f, 0),  // Crates
        new(0.4f, 0.4f, 0),    // Sacks
        new(0.6f, 0.8f, 0),    // Woodpile
        new(0.25f, 0.25f, 0),  // Signpost
        new(0.3f, 0.3f, 0),    // Scarecrow
        new(1.8f, 1.45f, 1),   // Cottage
        new(3.5f, 1.85f, 1),   // Inn
        new(1.4f, 1.25f, 1),   // Hovel
        new(1.7f, 0.45f, 0),   // RuinedWall
        new(1.0f, 0.95f, 0),   // StandingStones
    ];

    public static string FileName(PropKind kind) => FileStems[(int)kind] + ".glb";

    public static string ModelPath(PropKind kind) => ModelPaths[(int)kind];

    public static PropFootprint Footprint(PropKind kind) => Footprints[(int)kind];

    // Resolved once: AssetPaths combines on every read, and per-draw lookups must not allocate.
    private static readonly string[] ModelPaths = CreateModelPaths();

    private static string[] CreateModelPaths()
    {
        string[] paths = new string[FileStems.Length];
        for (int i = 0; i < paths.Length; i++)
        {
            paths[i] = AssetPaths.Animation(Path.Combine("props", FileStems[i] + ".glb"));
        }

        return paths;
    }
}

// One prop in the world: its kind, where its base sits (on the ground, centred), the heading of its front (+z
// of the model) as an angle about Y with 0 facing +Z and 90 degrees facing +X, and a uniform scale.
public readonly record struct PropPlacement(PropKind Kind, OpenTK.Mathematics.Vector3 Position, float YawDegrees, float Scale = 1f);
